#### benchmark (benchmark/c/native/benchmark.c:94)

```c
static double benchmark( void ) {
	stdlib_complex128_t z;
	double elapsed;
	double re;
	double im;
	double v;
	double t;
	int i;

	t = tic();
	for ( i = 0; i < ITERATIONS; i++ ) {
		re = rand_double();
		im = rand_double();
		z = stdlib_complex128( re, im );
		v = stdlib_complex128_imag( z );
		if ( v != v ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	elapsed = tic() - t;
	if ( v != v ) {
		printf( "should not return NaN\n" );
	}
	return elapsed;
}
```

#### main (examples/c/example.c:23)

```c
int main( void ) {
	const stdlib_complex128_t x[] = {
		stdlib_complex128( 5.0, 2.0 ),
		stdlib_complex128( -2.0, 1.0 ),
		stdlib_complex128( 0.0, -0.0 ),
		stdlib_complex128( 0.0/0.0, 0.0/0.0 )
	};

	int i;
	for ( i = 0; i < 4; i++ ) {
		printf( "imag(v) = %lf\n", stdlib_complex128_imag( x[ i ] ) );
	}
}
```
