'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var Complex128 = require( '@stdlib/complex-float64-ctor' );
var randu = require( '@stdlib/random-base-randu' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );
var pkg = require( './../package.json' ).name;
var imag = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var values;
	var im;
	var i;

	values = [
		new Complex128( randu(), randu() ),
		new Complex128( randu(), randu() ),
		new Complex128( randu(), randu() )
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		im = imag( values[ i%values.length ] );
		if ( isnan( im ) ) {
			b.fail( 'should not return NaN' );
		}
	}
	b.toc();
	if ( isnan( im ) ) {
		b.fail( 'should not return NaN' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":57,"totalLines":57,"truncated":false}},"title":"repos/pc-lib-3456/complex-float64-imag/benchmark/benchmark.js","time":{"start":1783262255144,"end":1783262255147}},"id":"prt_f32b6973f0019tfR0100ZjZwuU","sessionID":"ses_0cd4afe21ffepNGa76E07MpVDH","messageID":"msg_f32b68703001U1dOibzxfXuL9T"}}

